\label{prop:weightsparsop}
We have the following estimates:
    \begin{align*}
        \|\mathcal A_{\mathcal{S}}\|_{L^1(\omega)\to L^{1,\infty}(\omega)}
        &\lesssim [\omega]_{1,\mathcal{S}}\Bigl(\log[\omega]_{\infty,\mathcal{S}}+1\Bigr),&&\omega\in A_1^{\mathcal{S}};\\
        \|\mathcal A_{\mathcal{S}}\|_{L^p(\omega)\to L^{p,\infty}(\omega)}
        &\lesssim [\omega]_{p,\mathcal{S}}^{\frac 1p}[\omega]_{\infty,\mathcal{S}}^{\frac 1{p'}},&&\omega\in A_p^{\mathcal{S}},\qquad 1<p<\infty.
    \end{align*}
    Furthermore, for every $1\leq p<\infty$, if $\mathcal A_\mathcal{S}$ is bounded from $L^p(\omega)$ to $L^{p,\infty}(\omega)$, then $\omega\in A_p^\mathcal{S}$.

\label{prop: 2pesi}
Let $\nu\in\mathcal C_{\mathcal{S}}$. Let $1<p<\infty$ and $(\omega,\sigma)\in A_p^{\mathcal{S},2}(\nu)$. We have that
\begin{align*}
    \| \mathcal{A}_{\mathcal{S}}(\cdot\,\sigma)\| _{L^{p}(\sigma)\to L^{p}(\omega)}
    \lesssim&[\omega,\sigma]_{p,\mathcal{S}}^{\frac 1p}\big([\sigma]_{\infty,\mathcal{S}}^{\frac 1p}+[\omega]_{\infty,\mathcal{S}}^{\frac 1{p'}}\big).
\end{align*}
    Furthermore, if $\omega,\sigma\in A_\infty^\mathcal{S}(\nu)$ are such that $\mathcal A_\mathcal{S}(\cdot\,\sigma)$ is bounded from $L^p(\sigma)$ to $L^p(\omega)$, then $(\omega,\sigma)\in A^{\mathcal{S},2}_{p}(\nu)$.

The following estimates for $\mathcal{P}^+$, and hence for $\mathcal{P}$, hold true:
    \begin{align*}
        \| \mathcal{P}^+(\cdot\sigma)\| _{L^{p}_\alpha(\sigma)\to L^{p}_\alpha(\omega)}
&\lesssim[\omega,\sigma]_{p,\mathcal{Q}}^{\frac 1p}\big([\sigma]_{\infty,\mathcal{Q}}^{\frac 1p}+[\omega]_{\infty,\mathcal{Q}}^{\frac 1{p'}}\big)&&\text{if }(\omega,\sigma)\in B^{\mathcal{Q},2}_{p},\\
    \|\mathcal{P}^+\|_{L^1_\alpha(\omega)\to L^{1,\infty}_\alpha(\omega)}
        &\lesssim [\omega]_{1,\mathcal{Q}}\Bigl(\log[\omega]_{\infty,\mathcal{Q}}+1\Bigr)&&\text{if }\omega\in B_1^\mathcal{Q}.
    \end{align*}
    Furthermore, if $\mathcal{P}^+(\,\cdot\,\sigma)\colon L_\alpha^{p}(\sigma)\to L_\alpha^{p}(\omega)$ is bounded with $\omega,\sigma\in B_\infty^\mathcal{Q}$, then $(\omega,\sigma)\in  B^{\mathcal{Q},2}_{p}$, and if $\mathcal{P}^+\colon L_\alpha^{1}(\omega)\to L_\alpha^{1,\infty}(\omega)$ is bounded, then $\omega\in B_1^\mathcal{Q}$.

It is sufficient to show that the kernel $K_\alpha^+$ satisfies \eqref{eq:condKernel} with respect to $K_{\mathcal{A}_{\mathcal{S}}}$ for an appropriately chosen family $\mathcal{S}$. If we take $\mathcal{S}=\mathcal{Q}$, this means that we have to show
        \begin{equation}\label{eq: cond K+}
        K_\alpha^+(x,y)\approx \begin{dcases*}
            \mu_\alpha(T_{x\wedge y})^{-1},&\text{if }$x\wedge y\in\{x,y\}$\\
            \mu_\alpha(U_{x\wedge y})^{-1},&\text{if }$x\wedge y\not\in\{x,y\}$,
        \end{dcases*}
        \end{equation}
        by Proposition~\ref{prop: somma sect}. The estimates for $\mathcal{P}$ will then follow from those of $\mathcal{P}^+$. Let $z\in\mathfrak{X}$. Using that $E_\alpha(T_z^{(1)})\approx \mu_\alpha(T_z)$ and~\eqref{eq: hh}, for $x,y\in U_z^{(1)}$ we have 
        \begin{align}\label{eq: K_Q stime}
            |K_{T_z^{(1)},\alpha}(x,y)|\approx \begin{dcases*}
                \mu_\alpha(T_z)^{-1},&if $x\wedge y\neq z^{(1)}$,\\
                \mu_\alpha(U_z^{(1)})^{-1},&if $x\wedge y=z^{(1)}$.
            \end{dcases*}
        \end{align}
    Support considerations about $K_{Q,\alpha}$ yield
    \[K_\alpha^+(x,y)=|K_{T_{x\wedge y},\alpha}(x,y)|+\sum_{k=1}^{\infty}|K_{T_{x\wedge y}^{(k)},\alpha}(x,y)|,\]
    where the first term vanishes when $x\wedge y\in\{x,y\}$. Hence, by using~\eqref{eq: K_Q stime} we derive
    \[K_\alpha^+(x,y)\approx\begin{dcases*}
    \sum_{k=1}^{\infty}\mu_\alpha(T_{x\wedge y}^{(k-1)})^{-1},&\text{if }$x\wedge y\in\{x,y\}$,\\
        \mu_\alpha(U_{x\wedge y})^{-1}+\sum_{k=1}^{\infty}\mu_\alpha(T_{x\wedge y}^{(k-1)})^{-1},&\text{if }$x\wedge y\not\in\{x,y\}$,
    \end{dcases*}\]
    which by Proposition \ref{prop: somma sect} is what we wanted.

Let $\varphi\in L_\alpha^{\infty}$ and consider the associated Toeplitz operator
$T_{\varphi}f=\mathcal{P}(f\varphi)$. Notice that, if we take a weight $\omega$ and consider $\sigma=\omega^{-\frac{1}{p-1}}\varphi^{p'}$,
then
\begin{align*}
    \| T_{\varphi}f\|_{L_{\alpha}^{p}(\omega)}&= \|\mathcal{P}((f\varphi\sigma^{-1})\sigma)\|_{L_{\alpha}^{p}(\omega)}
    \\
    &\leq
    \| \mathcal{P}(\cdot\sigma)\|_{L_{\alpha}^{p}(\sigma)\to L_{\alpha}^{p}(\omega)}\|f\varphi\sigma^{-1}\| _{L_{\alpha}^{p}(\sigma)}
    =\|\mathcal{P}(\cdot\sigma)\|_{L_{\alpha}^{p}(\sigma)\to L_{\alpha}^{p}(\omega)}\| f\| _{L_{\alpha}^{p}(\omega)}.
\end{align*}
This means that
\begin{align*}
    \|T_\varphi\|_{L^p_\alpha(\omega)\to L^p_\alpha(\omega)}
    \leq&\| \mathcal{P}(\cdot\sigma)\|_{L_{\alpha}^{p}(\sigma)\to L_{\alpha}^{p}(\omega)}\\
    \lesssim & [\omega,(\omega^{-\frac 1p}\varphi)^{p'}]_{p,\mathcal{Q}}^{\frac 1p}\bigg(\big[(\omega^{-\frac 1p}\varphi)^{p'}\big]_{\infty,\mathcal{Q}}^{\frac 1p}+\big[\omega\big]_{\infty,\mathcal{Q}}^{\frac 1{p'}}\bigg).
\end{align*}
In the specific case in which $\varphi=\mu_{b}$ for some $b\geq0$,
notice that $T_{\mu_{b}}\colon L^{p}_\alpha\to L^{p}_\alpha$ if
\begin{align*}
[1,\mu_{bp'}]_{p,\mathcal{Q}}&=\sup_{Q\in\mathcal{Q}}\Bigg(\frac{\mu_{\alpha+bp'}(Q)}{\mu_{\alpha}(Q)}\Bigg)^{p-1}<+\infty,
\end{align*}
which is finite if and only if $\alpha+bp'>1$, i.e. $bp>(1-\alpha)(p-1)$.
This result extends the known result for Toeplitz operators on the disk (see~\cite{Zhu2007}) to the nondoubling discrete setting.

We have $m\sigma\in \mathcal C_\mathcal{T}=\mathcal C_\mathcal{U}=\mathcal C_\mathcal{Q}$ if and only if there exists $N\in\mathbb N$ and $0<c<1$ such that
    \begin{equation}\label{eq: S simili}
        S_{M+N}\leq c S_M,\qquad M\in\mathbb Z.
    \end{equation}
    Indeed, by the proof of Lemma~\ref{lem: equiv Carl}, saying that $m\sigma\in\mathcal C_\mathcal{T}$ is equivalent to having that for some $N\in\mathbb{N}$, 
    \begin{equation}\label{eq: ms Carl}
        m\sigma(T_x)\lesssim m\sigma(T_x\cap B(x,N-1)),\qquad x\in \mathfrak{X}.
    \end{equation} 
    Observe that for $x\in\mathfrak{X}$
    \begin{equation*}
        m\sigma(T_x\cap B(x,N-1))=\sum_{k=0}^{N-1}\sigma(|x|+k)\sum_{\substack{y\in T_x\\|y|=|x|+k}}m(y)=m(x)(S_{|x|}-S_{|x|+N}),
    \end{equation*} 
    which, together with~\eqref{eq: S simili}, gives~\eqref{eq: ms Carl}.

Assume $m\sigma\in\mathcal C_{\mathcal{Q}}$. The following estimates for $\mathcal{P}_m^+$, and hence for $\mathcal{P}_m$, hold true:
    \begin{align*}
        \| \mathcal{P}_m^+(\cdot\tau)\| _{L_{m\sigma}^{p}(\tau)\to L_{m\sigma}^{p}(\omega)}
&\lesssim[\omega,\tau]_{p,\mathcal{Q}}^{\frac 1p}\big([\tau]_{\infty,\mathcal{Q}}^{\frac 1p}+[\omega]_{\infty,\mathcal{Q}}^{\frac 1{p'}}\big)&&\text{if }(\omega,\tau)\in B^{\mathcal{Q},2}_{p}(m\sigma),\\
    \|\mathcal{P}_m^+\|_{L_{m\sigma}^1(\omega)\to L_{m\sigma}^{1,\infty}(\omega)}
         &\lesssim [\omega]_{1,\mathcal{Q}}\Bigl(\log[\omega]_{\infty,\mathcal{Q}}+1\Bigr)&&\text{if }\omega\in B_1^\mathcal{Q}(m\sigma).
        \end{align*}
        Furthermore, assume
        \begin{equation}\label{eq: ipo Km+}
            \sup_{x\in\mathfrak{X}}\frac{m(x)}{m(x^{(1)})}<1.
        \end{equation}
        If $\mathcal{P}_m^+(\,\cdot\,\tau)\colon L_{m\sigma}^{p}(\tau)\to L_{m\sigma}^{p}(\omega)$ is bounded with $\omega,\tau\in B_\infty^\mathcal{Q}(m\sigma)$, then $(\omega,\tau)\in B^{\mathcal{Q},2}_{p}(m\sigma)$, and if $\mathcal{P}_m^+\colon L_{m\sigma}^{1}(\omega)\to L_{m\sigma}^{1,\infty}(\omega)$ is bounded, then $\omega\in B_1^\mathcal{Q}(m\sigma)$.

