Let $\nu\in\mathcal C_\mathcal{Q}$ be a horocyclic measure on a horocyclic tree $\mathfrak{X}$, that is $\nu(x)=\nu(y)$ and $q(x)=q(y)$ if $|x|=|y|$. Let $\omega\colon \mathfrak{X}\to (0,+\infty)$ be a horocyclic weight. We have that 
    \[[\omega]_{p,\mathcal{T}}=[\omega]_{p,\mathcal{U}}=[\omega]_{p,\mathcal{Q}},\qquad 1\leq p<\infty. \]
    Furthermore, when $p>1$, we also have $[\omega]_{p,\mathcal{Q}}=[\omega]_{\widetilde{{B}_p}}$.

    Indeed, for the case $p>1$, observe that whenever $Q,R\in\mathcal{T}$ are such that $Q^{(1)}=R^{(1)}$, we have that $\omega(Q)=\omega(R)$ and similarly for $\omega^{-\frac{1}{p-1}}$, hence $\langle{\omega}\rangle_{Q}=\langle{\omega}\rangle_{R}$ and $\langle{\omega^{-\frac{1}{p-1}}}\rangle_{Q}=\langle{\omega^{-\frac{1}{p-1}}}\rangle_{R}$. Then
        \begin{equation*}
            [\omega]_{\widetilde{{B}_p}}= \sup_{\substack{Q,R\in\mathcal{T}\\Q^{(1)}=R^{(1)}}}\langle{\omega}\rangle_{Q}\langle{\omega^{-\frac{1}{p-1}}}\rangle_{R}^{p-1}=\sup_{Q\in\mathcal{T}}\langle{\omega}\rangle_{Q}\langle{\omega^{-\frac{1}{p-1}}}\rangle_{Q}^{p-1}=[\omega]_{p,\mathcal{T}}.
        \end{equation*}
        It is now sufficient to see that $[\omega]_{p,\mathcal{T}}=[\omega]_{p,\mathcal{U}}$. Notice that for a horocyclic weight $\eta\colon \mathfrak{X}\to (0,+\infty)$, we have
            \begin{align}\label{eq: media di eta}
                \langle{\eta}\rangle_{{x_Q}^{(1)}}=\frac{1}{q({x}^{(1)}_Q)\nu(Q)}\eta({x_Q}^{(1)})=\frac{1}{q({x}^{(1)}_Q)}\sum_{\substack{R\in\mathcal{T}\\R^{(1)}=Q^{(1)}}}\frac{\eta(R)}{\nu(Q)}=\langle{\eta}\rangle_{Q}.
        \end{align}
        Hence we get
        \begin{align*}
            [\omega]_{p,\mathcal{T}}= \sup_{Q\in\mathcal{T}}\langle{\omega}\rangle_{Q}\langle{\omega^{-\frac 1{p-1}}}\rangle_{Q}^{p-1}
            =\sup_{Q\in\mathcal{T}}\langle{\omega}\rangle_{{\dot Q}^{(1)}}\langle{\omega^{-\frac 1{p-1}}}\rangle_{{\dot Q}^{(1)}}^{p-1}=\sup_{U\in\mathcal{U}}\langle{\omega}\rangle_{U}\langle{\omega^{-\frac 1{p-1}}}\rangle_{U}^{p-1}=[\omega]_{p,\mathcal{U}}.
        \end{align*}
        Finally, for the case $p=1$, we use \eqref{eq: media di eta} together with the fact that, for every $T\in\mathcal{T}$,
\begin{equation*}\|\omega^{-1}1_{{\dot T}^{(1)}}\|_{\infty}=\max_{\substack {R\in\mathcal{T}\\R^{(1)}=T^{(1)}}}\|\omega^{-1}1_{R}\|_{\infty}=\|\omega^{-1}1_{T}\|_{\infty}, \end{equation*}
        to say that
        \begin{equation*}[\omega]_{1,\mathcal{T}}
        =\sup_{Q\in\mathcal{T}}\langle{\omega}\rangle_{Q}\|\omega^{-1}1_{Q}\|_\infty
        =\sup_{Q\in\mathcal{T}}\langle{\omega}\rangle_{{\dot Q}^{(1)}}\|\omega^{-1}1_{{\dot Q}^{(1)}}\|_\infty
        =\sup_{U\in\mathcal{U}}\langle{\omega}\rangle_{U}\|\omega^{-1}1_{U}\|_\infty
        =[\omega]_{1,\mathcal{U}}.
        \end{equation*}
